@pytest.mark.parametrize(\"lookup\", [\"1\", \"@production\", \"@latest\"])
@pytest.mark.parametrize(\"uri_source\", [\"explicit\", \"tracking\", \"global\"])
def test_prompt_cache_isolated_by_resolved_registry(lookup, uri_source, monkeypatch):
    monkeypatch.setattr(mlflow.tracking._model_registry.utils, \"_registry_uri\", None)
    monkeypatch.delenv(\"MLFLOW_REGISTRY_URI\", raising=False)
    clients = []
    for registry_uri in [\"http://registry-a\", \"http://registry-b\", \"http://registry-a\"]:
        if uri_source == \"explicit\":
            client = MlflowClient(tracking_uri=\"http://tracking\", registry_uri=registry_uri)
        elif uri_source == \"tracking\":
            client = MlflowClient(tracking_uri=registry_uri)
        else:
            monkeypatch.setattr(
                mlflow.tracking._model_registry.utils, \"_registry_uri\", registry_uri
            )
            client = MlflowClient(tracking_uri=\"http://tracking\")
        clients.append(client)

    uri = f\"prompts:/test_prompt{'/' if lookup.isdigit() else ''}{lookup}\"
    method = \"get_prompt_version\" if lookup.isdigit() else \"get_prompt_version_by_alias\"
    prompts = [object(), object()]
    with (
        mock.patch(
            f\"mlflow.tracking._model_registry.client.ModelRegistryClient.{method}\",
            side_effect=prompts,
        ) as fetch,
        mock.patch(
            \"mlflow.tracking.fluent._get_experiment_id\", return_value=None
        ) as experiment_id,
    ):
        assert clients[0].load_prompt(uri, cache_ttl_seconds=60) is prompts[0]
        assert clients[1].load_prompt(uri, cache_ttl_seconds=60) is prompts[1]
        assert clients[2].load_prompt(uri, cache_ttl_seconds=60) is prompts[0]
        assert clients[1].load_prompt(uri, cache_ttl_seconds=60) is prompts[1]
        assert fetch.call_args_list == [
            mock.call(\"test_prompt\", lookup.lstrip(\"@\")),
            mock.call(\"test_prompt\", lookup.lstrip(\"@\")),
        ]
        assert experiment_id.call_count == 2


@pytest.mark.parametrize(\"fails\", [False, True])
@pytest.mark.parametrize(
    (\"method\", \"args\", \"invalidated\"),
    [
        (\"set_prompt_alias\", (\"production\", 1), [\"@production\"]),
        (\"delete_prompt_alias\", (\"production\",), [\"@production\"]),
        (\"set_prompt_version_tag\", (1, \"key\", \"value\"), [\"1\", \"@production\", \"@latest\"]),
        (\"delete_prompt_version_tag\", (1, \"key\"), [\"1\", \"@production\", \"@latest\"]),
        (\"delete_prompt_version\", (1,), [\"1\", \"@production\", \"@latest\"]),
        (\"delete_prompt\", (), [\"1\", \"@production\", \"@latest\"]),
    ],
)
def test_prompt_cache_invalidation_isolated_by_registry(method, args, invalidated, fails):
    cache = PromptCache.get_instance()
    clients = [MlflowClient(registry_uri=f\"http://registry-{suffix}\") for suffix in [\"a\", \"b\"]]
    keys = {}
    for client in clients:
        for lookup in [\"1\", \"@production\", \"@latest\"]:
            uri = f\"prompts:/test_prompt{'/' if lookup.isdigit() else ''}{lookup}\"
            key = PromptCacheKey.from_uri(uri, registry_uri=client._registry_uri)
            keys[client._registry_uri, lookup] = key
            cache.set(key, \"cached\")

    registry_client = clients[0]._get_registry_client()
    with (
        mock.patch.object(
            registry_client, method, side_effect=MlflowException(\"failed\") if fails else None
        ) as update,
        mock.patch.object(registry_client, \"get_prompt_version\", return_value=object()) as validate,
    ):
        if fails:
            with pytest.raises(MlflowException, match=\"failed\"):
                getattr(clients[0], method)(\"test_prompt\", *args)
        else:
            getattr(clients[0], method)(\"test_prompt\", *args)
        update.assert_called_once_with(\"test_prompt\", *args)
        if method == \"set_prompt_alias\":
            validate.assert_called_once_with(\"test_prompt\", 1)
        else:
            validate.assert_not_called()

    for (registry_uri, lookup), key in keys.items():
        should_invalidate = (
            not fails and registry_uri == clients[0]._registry_uri and lookup in invalidated
        )
        assert cache.get(key) == (None if should_invalidate else \"cached\")
